<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['unique_identifier']);db()->beginTransaction();try{$s=db()->prepare("SELECT s.*,p.id product_id FROM sales s JOIN products p ON p.id=s.product_id WHERE p.unique_identifier=? AND s.seller_id=? AND s.id NOT IN(SELECT sale_id FROM returns) ORDER BY s.sold_at DESC LIMIT 1 FOR UPDATE");$s->execute([$d['unique_identifier'],$u['id']]);$sale=$s->fetch();if(!$sale)fail('Eligible sale not found',404);db()->prepare('INSERT INTO returns(sale_id,product_id,seller_id,reason,refund_amount) VALUES(?,?,?,?,?)')->execute([$sale['id'],$sale['product_id'],$u['id'],$d['reason']??null,$d['refund_amount']??$sale['selling_price']]);db()->prepare("UPDATE products SET status='available' WHERE id=?")->execute([$sale['product_id']]);db()->commit();out(['success'=>true,'message'=>'Return recorded; product is available again']);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();fail($e->getMessage(),400);}
